import styled from '@emotion/styled';
import { Layout, theme, saveDoc, updateDoc, SaveDialog, DocumentsMenu, DevToolkitNav } from '@atlantis/shared';
import { ChevronDown, GitBranch, Save } from 'lucide-react';
import { diffLines, diffStats, type DiffLine } from './diff';
import { EXAMPLES } from './examples';

// ─── Styled components ───────────────────────────────────────────────────────

